class Solution:

	def countEleLessThanOrEqual(self, array1, n1, array2, n2):
		n1_size = max(array1)
		n2_size = max(array2)
		holder = [0 for i in range(max(n1_size, n2_size) + 1)]
		for i in array2:
			holder[i] += 1
		count = 0
		for i in range(len(holder)):
			count += holder[i]
			holder[i] = count
		count = 0
		for i in range(n1):
			array1[i] = holder[array1[i]]
		return array1
